SUMMARIES = {
    "2606.00290": {"tldr": "用 flag algebra 系统性地计算了所有 6 个顶点的图的 inducibility 常数，解决了 30 个新情形，并在 32 个情形中建立了 perfect stability。", "motivation": "Inducibility 问题要求固定图 $F$ 的 induced copy 的最大渐近密度。5 个顶点以下的图已基本解决，6 个顶点的 78 个等价类是这个方向的下一步。", "method": "Flag algebra + 半正定规划（semidefinite programming）计算；对近极值图进行 stability 分析；对 78 个同构类（考虑补图）逐一处理。", "result": "在 36/78 个情形中得到了 inducibility 的精确上界（其中 30 个为新结果）。在 32 个情形中证明了 perfect stability，刻画了近极值图的结构。", "conclusion": "Flag algebra 对计算小图的 inducibility 极其有效。6 顶点图的情形基本解决，stability 分析揭示了极值图的丰富结构。", "future_work": "剩余 42 个 6 顶点图；向 7 顶点图扩展，需要更强的计算能力。"},
    "2606.00691": {"tldr": "解决了偶数阶图中 odd $[1,b]$-factor 存在的 sharp $A_\\alpha$ 谱条件，对 $\\alpha>1/2$ 给出完整的刻画。", "motivation": "谱极值图论用特征值给出结构性存在的充分条件。Chen 等人将 odd $[1,b]$-factor 问题归约为比较障碍图的谱半径，但具体比较悬而未决。", "method": "对障碍图族 $G_s=K_s\\nabla(K_{n-(b+1)s-1}\\cup(bs+1)K_1)$ 的 $A_\\alpha$ 谱半径进行代数和分析比较。", "result": "确定了障碍图族中 $A_\\alpha$ 谱半径最大的唯一图，从而给出了 $\\alpha>1/2$ 且 $n$ 充分大偶数时 odd $[1,b]$-factor 存在的 sharp 谱条件。", "conclusion": "$A_\\alpha$ 谱方法成功刻画了 odd $[1,b]$-factor 的存在性，统一并推广了先前对特定 $b,\\alpha$ 的结果。", "future_work": "$\\alpha\\le 1/2$ 的情形；向 $[a,b]$-factor（$a>1$）扩展。"},
    "2606.00976": {"tldr": "确定了 $t$-fan 和偶数 wheel graph 的 rainbow Turán 数精确值，推广了 Keevash–Mubayi–Sudakov–Verstraëte 的框架。", "motivation": "Rainbow Turán 数 $\\mathrm{ex}^*(n,H)$ 禁止 properly edge-colored 图中出现 rainbow $H$。目前除完全图外只有极少数图的精确值已知。Fan 和 wheel 是继边和三角形之后最自然的候选。", "method": "对极值构造做 stability 分析；对 rainbow-$H$-free 的染色结构进行刻画；匹配上下界。", "result": "对所有充分大的 $n$，确定了 $t$-fan 和偶数 wheel $W_{2k}$ 的 $\\mathrm{ex}^*(n,H)$ 精确值。", "conclusion": "Fan 和偶数 wheel 的 rainbow Turán 问题展现出干净的极值结构，极值构造是 Turán 图的自然推广。", "future_work": "奇数 wheel graph；其他结构更复杂的图的 rainbow Turán 极值问题。"},
    "2606.01996": {"tldr": "证明了偶圈和奇路的 threshold Ramsey multiplicity 的新上界，表明它们的衰减速度比多项式还快。", "motivation": "Threshold Ramsey multiplicity $m(H)$ 是 $K_{r(H)}$ 的任意红蓝边染色中单色 $H$ 的副本数的最小值。理解路和圈的 $m(H)$ 是 Ramsey 理论与计数问题的交叉核心问题。", "method": "组合计数论证 + 局部随机构造（带结构修改的随机染色）来限制单色副本数量。", "result": "$m(C_{2t})\\le t^{-\\gamma+o(1)}(2t-1)!/2$ 和 $m(P_{2t+1})\\le t^{-\\gamma+o(1)}t/2$（$\\gamma>0$），即 threshold Ramsey multiplicity 比任何多项式衰减都快。", "conclusion": "偶圈和奇路在 Ramsey 阈值处被强制出现的单色副本惊人地少——远少于完全图中的总副本数。", "future_work": "确定最优的 $\\gamma$；向奇圈和偶路扩展；与 Kohayakawa–Kreuter 猜想的联系。"},
    "2606.02030": {"tldr": "引入 DOM-bounded 图类作为 $\\chi$-bounded 图类在 domatic 意义下的类比，并与 Gyárfás–Sumner 猜想建立联系。", "motivation": "$\\chi$-boundedness（用团数界染色数）是核心概念。Domatic 数 $\\mathrm{dom}(G)\\le\\delta(G)+1$ 是染色数 $\\chi(G)\\ge\\omega(G)$ 的对偶，因此自然有 DOM-bounded 的平行理论。", "method": "结构图论方法；构造 domatic 数相对最小度有界的图类；建立与禁止诱导子图理论的联系。", "result": "给出 DOM-bounded 图类的形式化定义和基本性质；在 domatic 背景下建立了与经典 $\\chi$-boundedness 结果对应的结论；分析了与 Gyárfás–Sumner 猜想的关系。", "conclusion": "DOM-boundedness 是一个丰富的框架，与经典结果平行但又揭示了新的结构现象。", "future_work": "用禁止诱导子图完全刻画 DOM-bounded 图类；Strong Perfect Graph Theorem 的 domatic 版本。"},
    "2606.02135": {"tldr": "建立了超图 Turán 问题与经典极值集合论（Erdős–Ko–Rado、$L$-intersecting 族、Erdős 匹配问题）之间的系统性联系。", "motivation": "超图 Turán 问题异常困难。将其与极值集合论联系起来——后者的工具更多——为得到 Turán 密度的上界提供了新途径。", "method": "构造自然的均匀超图族，使其 Turán 密度上界归约为经典极值集合论问题（Erdős–Ko–Rado、$L$-intersecting 族、Erdős 匹配问题）的组合归约。", "result": "确定了若干超图族，其 Turán 密度上界直接来自经典极值集合论结果。提供了系统性的归约框架。", "conclusion": "极值集合论是处理超图 Turán 问题的有力工具；许多公开的 Turán 密度问题可能可以在此框架下重新表述。", "future_work": "将框架应用于具体关心的超图（如 Fano plane、expanded triangles）；以 Turán 应用为动机发展新的极值集合论结果。"},
    "2606.02160": {"tldr": "确定了随机 $F$-factor 扰动下图的 pancyclicity 的 sharp 最小度阈值，解决了 Espuny Díaz–Girão (2023) 的猜想。", "motivation": "随机扰动图结合了确定性最小度条件与随机边撒入。扰动 $K_r$-factor 的 Hamiltonicity 阈值已被猜想，但更强的 pancyclic 结论仍是公开问题。", "method": "引入两个新参数 $\\tau_{\\mathrm{pc}}(F)$ 和 $\\alpha^*_{\\mathrm{pan}}(F)$；使用吸收方法（absorption method）结合概率论证；对 $F$-factor 进行结构分析。", "result": "随机 $K_r$-factor 扰动下 pancyclicity 的 sharp 最小度阈值；对一般连通 $F$ 给出了用新参数表示的一般上界。", "conclusion": "扰动图的 pancyclicity 阈值由两个自然的结构参数控制；Espuny Díaz–Girão 猜想以更强的形式被解决。", "future_work": "对更大的图族 $F$ 精确确定 $\\tau_{\\mathrm{pc}}(F)$ 和 $\\alpha^*_{\\mathrm{pan}}(F)$；向超图和其他 spanning structures 推广。"},
    "2606.02210": {"tldr": "确认了 Balogh–Clemen–Lidický 猜想：平衡二部构造是 $K_5^3$ 的 $\\ell_2$-norm Turán 问题的唯一极值构造，并确定了 $K_5^3$-free 3-图中 cliques 的精确最大数量。", "motivation": "超图的 $\\ell_2$-norm Turán 问题推广了经典 Turán 问题。$K_5^3$ 情形已渐近解决，但极值构造的唯一性仍为猜想。", "method": "顶点染色图的 Turán 定理作为核心工具；将超图极值问题归约为染色图极值问题；stability 分析和精确优化。", "result": "平衡二部构造是 $\\ell_2$-norm $K_5^3$ Turán 问题的唯一极值 3-图（对所有充分大 $n$）。确定了 $K_5^3$-free 3-图中 cliques 的精确最大数量，验证了 Frankl–Gryaznov–Talebanfard 猜想的对应情形。", "conclusion": "顶点染色图的 Turán 理论为超图极值问题提供了有力的归约手段。$K_5^3$ 情形现已完全解决。", "future_work": "将顶点染色 Turán 方法推广到其他超图 Turán 问题；向更大的 $K_t^r$ 扩展。"},
    "2606.02279": {"tldr": "建立了 $F$-free 可 trace 图中固定顶点间 Hamiltonian 路径数量的 sharp 二分性。", "motivation": "给定一个 $F$-free 图，若它的某两个顶点间存在 Hamiltonian 路径，那么到底有多少条？这联系了禁止诱导子图理论与 Hamiltonian 路径计数。", "method": "对 Hamiltonian 路径数量少的 $F$-free 图进行结构刻画；对反面情形构造无限族；正面情形使用计数论证。", "result": "若 $F$ 不是某个 $P_3+sP_1$ 的诱导子图，则存在无限族 $F$-free 图，其指定顶点间仅有恰好一条 Hamiltonian 路径。否则，路径数随图的阶数增长。", "conclusion": "一个 sharp 二分性：障碍恰好是 $P_3+sP_1$ 的诱导子图。这精确刻画了何时 $F$-free 图强制出现多条 Hamiltonian 路径。", "future_work": "正面情形的 Hamiltonian 路径数量的定量下界；向其他 spanning structures 推广。"},
    "2606.02356": {"tldr": "确定了不含长度 $1\\bmod 3$ 的圈的 2-连通图的极值边数，推进了 Burr–Erdős (1976) 的问题。", "motivation": "Burr 和 Erdős (1976) 猜想：不含长度 $\\ell\\bmod k$ 的圈的图有线性多条边。Bollobás 证明了猜想；Erdős 进一步要求精确极值数，这对大多数参数仍是公开问题。", "method": "对不含 $1\\bmod 3$ 圈的 2-连通图进行结构分析；刻画极值构造；使用度数论证。", "result": "确定了不含 $1\\bmod 3$ 圈的 2-连通图的精确极值数。将已知情形从 $k\\le 4$ 向前推进。", "conclusion": "Burr–Erdős 问题正逐步被逐情形解决。2-连通且禁止 $1\\bmod 3$ 圈的情形展现出干净的极值结构。", "future_work": "向一般图（不一定 2-连通）推广；模 3 的其他余数。"},
    "2606.02389": {"tldr": "以强形式证明了 Schelp 的 Burr–Erdős 树猜想度数版本。", "motivation": "Burr–Erdős 猜想（任意 $n$ 顶点树的 Ramsey 数 $\\le 2n-2$）已被 Zhao 证明。Schelp 问：宿主图的最小度条件能否保证每个有界度树的单色副本？", "method": "Szemerédi regularity lemma + 稠密图中树的嵌入技术 + absorption 风格论证（从正则划分拼装树嵌入）。", "result": "对任意 $\\varepsilon>0$ 和 $\\Delta$，若 $G$ 有 $N\\ge(2+\\varepsilon)n$ 个顶点且最小度 $\\ge\\lfloor 3N/4\\rfloor$，则任意 2-边染色包含每个 $n$ 顶点且最大度 $\\le\\Delta$ 的树的单色副本。以强形式证明了 Schelp 猜想。", "conclusion": "Burr–Erdős 猜想的度数版本以相同的渐近界成立：树在稠密宿主图中是 Ramsey-不可避免的。", "future_work": "将 $(2+\\varepsilon)$ 改进为 $2$；去掉有界度条件；多色推广。"},
    "2606.02541": {"tldr": "证明了 3 色 van der Waerden 数 $w(k;3)$ 超指数增长：对充分大的 $k$，$w(k;3)>2^{k\\log^* k/4}$。由 Jacob Fox 与 Zach Hunter 合作完成。", "motivation": "Van der Waerden 数 $w(k;r)$ 是 Ramsey 理论最基本的量之一。已知指数下界，但 $r=3$ 时能否超指数是重大公开问题。", "method": "概率构造 + 新颖的递归染色方案；density Hales–Jewett 定理；利用等差数列结构的 bootstrap 论证。", "result": "对充分大 $k$，$w(k;3)>2^{k\\log^* k/4}$。作为推论解决了 Erdős–Graham 关于 canonical van der Waerden 数的问题。", "conclusion": "3 色 van der Waerden 数超指数增长——这是 Fox 和 Hunter 的标志性结果。$\\log^*$ 因子暗示增长甚至可以更快。", "future_work": "将 $\\log^*$ 因子改进为 $\\log k$ 的幂次；向 $r\\ge 4$ 色推广；加强与 canonical van der Waerden 数的联系。"},
    "2606.02464": {"tldr": "证明了对不可观测队列的门控准入策略（gated admission）在同等吞吐量下随机优于随机路由，且福利增益可任意大。", "motivation": "不可观测队列的准入控制是排队论的基本问题。有记忆的控制器（门控准入）可能优于无记忆的（随机稀释）。", "method": "随机序（stochastic ordering）技术；M/M/1 队列的门控准入分析；定义 Price of Forgetting 为随机路由与最优门控准入的福利比。", "result": "门控准入在同等吞吐量下随机优于随机路由。刻画了福利最大化的阈值。Price of Forgetting 无界，尽管绝对福利增益保持有界。", "conclusion": "记忆在准入控制中极其有价值：相对福利增益可以任意大，证明了状态依赖策略的必要性。", "future_work": "向多服务器队列和排队网络推广；门控准入之外的其他基于记忆的策略。"},
}
